package net.civeira.phylax.features.access.userpersonalapikey.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ScopesVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property scopes of user personal api key ")
  void test_scopes_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> ScopesVO.tryFrom(null));
    Assertions.assertEquals("one", ScopesVO.from("one").getScopes());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> ScopesVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", ScopesVO.from("one").toString());
  }
}
